                cloudGradient.addColorStop(0.55, 'rgba(' + shade + ',' + (shade + 6) + ',243,' + (0.5 + moistureValue * 0.2) + ')');
                cloudGradient.addColorStop(1, 'rgba(148,163,184,0)');
