              evapPs.push({ x: Math.random() * cW * 0.55 / dpr, y: cH * 0.6 / dpr + Math.random() * cH * 0.1 / dpr, size: 1.5 + Math.random() * 2, speed: 0.3 + Math.random() * 0.5, phase: Math.random() * Math.PI * 2 });

